class Solution:
    def findKthLargest(self, nums: List[int], k: int) -> int:
        heap = []                              # min-heap holding the k largest seen so far
        for num in nums:
            heapq.heappush(heap, num)          # O(log k): the heap never exceeds k + 1 items
            if len(heap) > k:
                heapq.heappop(heap)            # evict the smallest, keeping the k largest
        return heap[0]                         # smallest of the top k = k-th largest
